1	import type { DesignContext, DesignDecisions, ProductFrame } from "prax-runtime";
2	import { zodIssues } from "prax-runtime";
3	import { SdirSchema, SdirV02Schema, type Sdir, type SdirIssue, type SdirValidation } from "./contracts.js";
4	import { patternSurfaceContract } from "./surfaces.js";
5	
6	export const FORBIDDEN_KEY = /(^|_)(width|height|padding|margin|display|grid|flex|color|font|radius|shadow|css|class|classname|component|framework|tailwind|pixel|px)($|_)/i;
7	export const FORBIDDEN_VALUE = /(\d+(?:\.\d+)?px\b|display\s*:\s*(?:flex|grid)|grid-template|rounded-(?:sm|md|lg|xl)|rounded\s+corners|(?:Radix|Vue|React|Compose)[A-Z]\w*)/i;
8	const KNOWN_ROLES = new Set([
9	  "dominant_workspace",
10	  "contextual_inspector",
11	  "primary_navigation",
12	  "supporting_toolbar",
13	  "collection",
14	  "detail",
15	  "configuration_sections",
16	]);
17	const KNOWN_INTENTS = new Set([
18	  "hierarchical_flow",
19	  "spatial_overview",
20	  "comparison_group",
21	  "selection_driven",
22	  "direct_selection",
23	  "pan_zoom",
24	  "progressive_inspection",
25	  "filter_then_inspect",
26	  "preserve_context",
27	  "keyboard_equivalent",
28	]);
29	
30	export function renderLeakIssues(value: unknown, path = "sdir"): string[] {
31	  if (Array.isArray(value)) {
32	    return value.flatMap((item, index) => renderLeakIssues(item, `${path}.${index}`));
33	  }
34	  if (value !== null && typeof value === "object") {
35	    return Object.entries(value).flatMap(([key, child]) => [
36	      ...(FORBIDDEN_KEY.test(key) ? [`${path}.${key}: render-level key is forbidden in SDIR`] : []),
37	      ...renderLeakIssues(child, `${path}.${key}`),
38	    ]);
39	  }
40	  return typeof value === "string" && FORBIDDEN_VALUE.test(value)
41	    ? [`${path}: render-level value '${value}' is forbidden in SDIR`]
42	    : [];
43	}
44	
45	function experimentalVocabularyIssues(sdir: Sdir): string[] {
46	  const values = [
47	    ...sdir.screen.regions.map((region) => region.role),
48	    ...sdir.screen.regions.flatMap((region) => region.behavior_intent),
49	    ...sdir.screen.interaction_intents,
50	  ];
51	  return values
52	    .filter(
53	      (value) =>
54	        !KNOWN_ROLES.has(value) &&
55	        !KNOWN_INTENTS.has(value) &&
56	        !value.startsWith("experimental:"),
57	    )
58	    .map((value) => `Unknown semantic vocabulary '${value}' must be marked experimental:.`);
59	}
