1	/* 维象 · 多维数据探索 — cell-j13-s10 (explore × dimensional-space)
2	 * 纯静态单屏应用：零依赖、零构建、file:// 直接打开。
3	 * 数据由确定性种子生成器在解析时同步构建 —— 无网络请求、无加载态，首屏即就绪。
4	 *
5	 * 认知保持（成功标准）：切换 X/Y/颜色维度只改变投影映射，
6	 *   selection / filters / 历史栈（投影轨迹）全部跨维度切换保持。
7	 * 状态归属与回退（验收种子）：每条过滤器归属到维度（芯片标注），
8	 *   每次视图变更加入命名快照栈，可撤销/重做，也可在轨迹中点击任意一步回退。
9	 */
10	(function () {
11	'use strict';
12	
13	/* =====================================================================
14	 * 0. 确定性数据生成（内联，无网络）
15	 * ===================================================================== */
16	function mulberry32(a) {
17	  return function () {
18	    a |= 0; a = (a + 0x6D2B79F5) | 0;
19	    var t = Math.imul(a ^ (a >>> 15), 1 | a);
20	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
21	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
22	  };
23	}
24	var rand = mulberry32(0x20260913);
25	function randn() { // Box–Muller
26	  var u = 0, v = 0;
27	  while (u === 0) u = rand();
28	  while (v === 0) v = rand();
29	  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
30	}
31	function clamp(v, a, b) { return Math.min(b, Math.max(a, v)); }
32	function r1(v) { return Math.round(v * 10) / 10; }
33	function sig(x) { return 1 / (1 + Math.exp(-x)); }
34	
35	var REGIONS = [
36	  { name: '华东沿海', temp: 16.5, precip: 1150, dev: 0.35 },
37	  { name: '华南沿海', temp: 22.5, precip: 1700, dev: 0.25 },
38	  { name: '北方平原', temp: 13.0, precip: 560,  dev: 0.00 },
39	  { name: '西南山地', temp: 15.5, precip: 1050, dev: -0.15 },
40	  { name: '西部内陆', temp: 11.0, precip: 480,  dev: -0.30 },
41	  { name: '东北寒地', temp: 6.5,  precip: 620,  dev: -0.05 }
42	];
43	var TIERS = ['超大城市', '特大城市', '大城市', '中小城市'];
44	var PREFIX = ['云港','临川','新岚','青石','白泉','永安','宁川','高坪','清河','龙溪',
45	              '南屿','东津','西泽','北岭','朔方','望城','曲阳','桐川','兰泽','鹤鸣',
46	              '沙汀','枫溪','月浦','芦湾','星屿','竹逸','梅川','荷塘','柳川','桂语',
47	              '榕荫','泉川','云崖','雪川','虹川','锦川','沧浪','翠微','丹丘','鹿鸣'];
48	var SUFFIX = ['市', '州', '城', '港', '原', '谷'];
49	
50	var DATA = [];
51	(function buildDataset() {
52	  for (var i = 0; i < 240; i++) {
53	    var reg = REGIONS[i % REGIONS.length];
54	    var pop = clamp(Math.round(Math.exp(2.9 + 0.95 * randn()) * 6), 18, 3400);
55	    var area = clamp(Math.round(pop * (0.85 + rand() * 1.5) + 15 + rand() * 45), 12, 5200);
56	    var temp = r1(reg.temp + randn() * 2.4);
57	    var precip = Math.round(reg.precip * (0.72 + rand() * 0.62) / 10) * 10;
58	    var d = clamp(randn() * 0.85 + reg.dev, -2.2, 2.2);
59	    var gdp = r1(clamp(5 + 16 * sig(1.5 * d) + rand() * 2 + randn() * 1.2, 3, 30));
60	    var aqi = Math.round(clamp(78 - 16 * sig(1.3 * d) - (precip - 500) / 60 + randn() * 14, 22, 165));
61	    var happy = Math.round(clamp(52 + 16 * d - 0.06 * (aqi - 60) + randn() * 5, 20, 96));
62	    var beds = r1(clamp(2.5 + 4.2 * sig(1.2 * d) + randn() * 0.7, 0.8, 12));
63	    var commute = Math.round(clamp(14 + 4.6 * Math.log(pop + 20) + randn() * 4, 12, 70));
64	    var univ = Math.round(clamp(2 + 42 * sig(1.35 * d) + randn() * 6, 0, 88));
65	    var housing = r1(clamp(3.5 + 8.5 * sig(1.4 * d) + Math.max(0, Math.log10(pop / 80)) * 2.2 + randn() * 1.4, 1.5, 32));
66	    var startup = Math.round(clamp(34 + 24 * sig(1.05 * d) + randn() * 7, 8, 98));
67	    var culture = Math.round(clamp(2 + 34 * sig(1.15 * d) + randn() * 6, 0, 70));
68	    var tier = pop >= 1000 ? TIERS[0] : pop >= 500 ? TIERS[1] : pop >= 200 ? TIERS[2] : TIERS[3];
69	    DATA.push({
70	      id: i, name: PREFIX[i % 40] + SUFFIX[(i / 40) | 0],
71	      region: reg.name, tier: tier,
72	      pop: pop, area: area, gdp: gdp, housing: housing,
73	      temp: temp, precip: precip, aqi: aqi,
74	      beds: beds, commute: commute, univ: univ, happy: happy,
75	      startup: startup, culture: culture
76	    });
77	  }
78	})();
79	
80	/* ---------- 维度元数据（15 维 = 13 数值 + 2 分类；层级：5 个主题组） ---------- */
81	var GROUPS = [
82	  { id: 'scale',      name: '规模与经济' },
83	  { id: 'climate',    name: '气候与环境' },
84	  { id: 'livability', name: '民生与公共服务' },
85	  { id: 'vitality',   name: '活力与创新' },
86	  { id: 'category',   name: '分类维度' }
87	];
88	var DIMS = [
89	  { id: 'pop',     name: '人口',         unit: '万人', type: 'num', group: 'scale' },
90	  { id: 'area',    name: '建成区面积',   unit: 'km²',  type: 'num', group: 'scale' },
91	  { id: 'gdp',     name: '人均GDP',      unit: '万元', type: 'num', group: 'scale', fmt: 1 },
92	  { id: 'housing', name: '房价收入比',   unit: '倍',   type: 'num', group: 'scale', fmt: 1 },
93	  { id: 'temp',    name: '年均气温',     unit: '°C',   type: 'num', group: 'climate', fmt: 1 },
94	  { id: 'precip',  name: '年降水量',     unit: 'mm',   type: 'num', group: 'climate' },
95	  { id: 'aqi',     name: '空气质量指数', unit: 'AQI',  type: 'num', group: 'climate' },
96	  { id: 'beds',    name: '每千人床位',   unit: '张',   type: 'num', group: 'livability', fmt: 1 },
97	  { id: 'commute', name: '平均通勤',     unit: '分钟', type: 'num', group: 'livability' },
98	  { id: 'univ',    name: '高校数量',     unit: '所',   type: 'num', group: 'livability' },
99	  { id: 'happy',   name: '幸福指数',     unit: '/100', type: 'num', group: 'livability' },
100	  { id: 'startup', name: '创业活跃度',   unit: '/100', type: 'num', group: 'vitality' },
101	  { id: 'culture', name: '文化场馆',     unit: '个',   type: 'num', group: 'vitality' },
102	  { id: 'region',  name: '区域',         type: 'cat',  group: 'category', cats: REGIONS.map(function (r) { return r.name; }) },
103	  { id: 'tier',    name: '城市等级',     type: 'cat',  group: 'category', cats: TIERS.slice() }
104	];
105	var DIM = {};
106	DIMS.forEach(function (dm) { DIM[dm.id] = dm; });
107	
108	/* 各数值维度的全量范围 —— 轴域固定不随过滤跳动（方向锚点） */
109	var EXTENT = {};
110	DIMS.forEach(function (dm) {
111	  if (dm.type !== 'num') return;
112	  var lo = Infinity, hi = -Infinity;
113	  DATA.forEach(function (r) { var v = r[dm.id]; if (v < lo) lo = v; if (v > hi) hi = v; });
114	  EXTENT[dm.id] = { min: lo, max: hi };
115	});
116	
117	/* ---------- 颜色（dataviz 参考实例：已验证槽序；relief = 图例+提示+表格） ---------- */
118	var CAT_PALETTE = {
119	  region: ['#2a78d6', '#eb6834', '#008300', '#4a3aa7', '#e34948', '#1baf7a'],
120	  tier:   ['#2a78d6', '#eb6834', '#008300', '#4a3aa7']
121	};
122	var SEQ = ['#cde2fb', '#9ec5f4', '#6da7ec', '#3987e5', '#256abf', '#184f95', '#0d366b'];
123	function seqColor(t) {
124	  t = clamp(t, 0, 1);
125	  var x = t * (SEQ.length - 1), i = Math.min(SEQ.length - 2, Math.floor(x)), f = x - i;
126	  var a = SEQ[i], b = SEQ[i + 1], out = '#';
127	  for (var k = 0; k < 3; k++) {
128	    var ch = Math.round(parseInt(a.substr(1 + k * 2, 2), 16) * (1 - f) + parseInt(b.substr(1 + k * 2, 2), 16) * f);
129	    out += ('0' + ch.toString(16)).slice(-2);
130	  }
131	  return out;
132	}
133	function colorOf(dimId, rec) {
134	  var dm = DIM[dimId];
135	  if (dm.type === 'cat') {
136	    var idx = dm.cats.indexOf(rec[dimId]);
137	    return (CAT_PALETTE[dimId] || CAT_PALETTE.region)[idx] || '#52514e';
138	  }
139	  var e = EXTENT[dimId];
140	  return seqColor((rec[dimId] - e.min) / (e.max - e.min));
141	}
142	
143	/* ---------- 格式化 / 刻度 ---------- */
144	function fmtVal(dimId, v) {
145	  var dm = DIM[dimId];
146	  if (dm.type === 'cat') return String(v);
147	  return dm.fmt === 1 ? (+v).toFixed(1) : String(Math.round(v));
148	}
149	function fmtNum(dimId, v) {
150	  var dm = DIM[dimId];
151	  var s = dm.type === 'cat' ? String(v) : (dm.fmt === 1 ? (+v).toFixed(1) : String(Math.round(v)));
152	  return dm.unit ? s + ' ' + dm.unit : s;
153	}
154	function niceTicks(min, max, count) {
155	  var span = max - min;
156	  if (!(span > 0)) return [min];
157	  var raw = span / (count || 5);
158	  var mag = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10));
159	  var norm = raw / mag;
160	  var step = (norm < 1.5 ? 1 : norm < 3.5 ? 2 : norm < 7.5 ? 5 : 10) * mag;
161	  var out = [], v = Math.ceil(min / step) * step;
