      cb.addEventListener('change', onCatChange);
      lab.appendChild(cb);
      lab.appendChild(document.createTextNode(c));
      list.appendChild(lab);
    });
    ed.appendChild(list);
  }
  var foot = el('div', { class: 'editor-foot' });
