/* =====================================================================
 * 4. 散点投影（SVG，轴域固定于全量范围）
 * ===================================================================== */
function scales() {
  var xe = EXTENT[state.x], ye = EXTENT[state.y];
  var iw = chartW - M.l - M.r, ih = chartH - M.t - M.b;
  return {
    xe: xe, ye: ye, iw: iw, ih: ih,
    x: function (v) { return M.l + (v - xe.min) / (xe.max - xe.min) * iw; },
