function renderTrail() {
  var ol = $('#trail');
  ol.textContent = '';
  for (var i = tape.length - 1; i >= 0; i--) {
    (function (i) {
      var li = el('li', { class: i === ptr ? 'current' : i > ptr ? 'future' : '' });
      if (i === ptr) li.setAttribute('aria-current', 'step');
