602	  var r = chartwrap.getBoundingClientRect();
603	  var x = ev.clientX - r.left + 14, y = ev.clientY - r.top + 14;
604	  if (x + 180 > r.width) x -= 200; if (y + 90 > r.height) y -= 100;
605	  tooltip.style.left = x + 'px'; tooltip.style.top = y + 'px';
606	});
