755	      var x = el('button', { type: 'button', class: 'chip-x', title: '从选择中移除 ' + DATA[id].name, 'aria-label': '从选择中移除 ' + DATA[id].name }, '×');
756	      x.addEventListener('click', function () {
757	        state.selection.delete(id);
758	        if (state.lastSel === id) state.lastSel = state.selection.size ? Array.from(state.selection)[state.selection.size - 1] : null;
759	        push('取消选中 ' + DATA[id].name, '选择');
