802	      if (i === ptr) li.setAttribute('aria-current', 'step');
803	      var b = el('button', { type: 'button', class: 'trail-item', title: '回退到这一步（可继续撤销/重做）' });
804	      b.appendChild(el('span', { class: 'step' }, '#' + (i + 1)));
805	      b.appendChild(el('span', { class: 'lbl' }, tape[i].label));
806	      b.appendChild(el('span', { class: 'own' }, tape[i].owner));
807	      b.addEventListener('click', function () { jumpTo(i); });
808	      li.appendChild(b);
809	      ol.appendChild(li);
810	    })(i);
811	  }
812	  if (!tape.length) ol.appendChild(el('li', { class: 'inspector-empty' }, '暂无历史'));
