814	
815	/* =====================================================================
816	 * 6. 全局事件 / 启动
817	 * ===================================================================== */
818	$('#btn-undo').addEventListener('click', undo);
819	$('#btn-redo').addEventListener('click', redo);
820	$('#btn-reset').addEventListener('click', function () {
821	  restore(tape[0].snap);
822	  push('重置视图', '全局');
823	  announce('已重置到初始视图（可通过撤销回到重置前）');
824	});
825	document.addEventListener('keydown', function (ev) {
826	  var mod = ev.ctrlKey || ev.metaKey;
827	  if (mod && !ev.altKey && ev.key.toLowerCase() === 'z') {
828	    ev.preventDefault();
829	    if (ev.shiftKey) redo(); else undo();
830	  } else if (mod && !ev.altKey && ev.key.toLowerCase() === 'y') {
831	    ev.preventDefault(); redo();
832	  } else if (ev.key === 'Escape' && !ev.ctrlKey && !ev.metaKey &&
833	             document.activeElement.tagName !== 'INPUT') {
834	    clearSelection();
