/* =====================================================================
 * 1. 状态：投影角色 + 过滤（归属到维度）+ 选择 + 命名快照栈
 * ===================================================================== */
var state = {
  x: 'gdp', y: 'happy', color: 'region',
  filters: Object.create(null),      // dimId -> {kind:'num',min,max} | {kind:'cat',on:Set}
  selection: new Set(),              // 记录 id 集合（跨投影保持）
  lastSel: null
};
