    var c = svgEl('circle', {
      cx: sc.x(rec[state.x]).toFixed(1), cy: sc.y(rec[state.y]).toFixed(1), r: 4.5,
      fill: colorOf(state.color, rec), 'fill-opacity': vis ? 0.88 : 0.10,
