    rings.appendChild(svgEl('circle', { cx: sc.x(rec[state.x]).toFixed(1), cy: sc.y(rec[state.y]).toFixed(1), r: 7.5, fill: 'none', stroke: '#0b0b0b', 'stroke-width': 2 }));
