      width: 20, height: 20, rx: 5, fill: 'none', stroke: '#0b0b0b', 'stroke-width': 1.6, 'stroke-dasharray': '4 3'
    }));
  }
  chart._visible = visible; chart._sc = sc;
}
function cursorRec(visible) {
