  i = i < 0 ? 0 : clamp(i + delta, 0, visible.length - 1);
  cursorId = visible[i].id;
  renderChart();
  if (announceIt !== false) {
    var rec = visible[i];
    announce(rec.name + '：' + DIM[state.x].name + ' ' + fmtNum(state.x, rec[state.x]) + '，' + DIM[state.y].name + ' ' + fmtNum(state.y, rec[state.y]));
